def transform(grid):
    h, w = len(grid), len(grid[0])

    # Each macro-cell contains an N-by-N tile, with one blank row/column
    # between tiles: the full dimension is N*(N+1)-1.
    n = next(
        (k for k in range(1, min(h, w) + 1)
         if k * (k + 1) - 1 == h and k * (k + 1) - 1 == w),
        None
    )
    if n is None:
        return [[0 if v == 3 else v for v in row] for row in grid]

    pitch = n + 1
    tiles = []
    for i in range(n):
        for j in range(n):
            r, c = i * pitch, j * pitch
            tile = tuple(
                tuple(grid[r + a][c:c + n]) for a in range(n)
            )
            if not any(v == 3 for row in tile for v in row):
                count = sum(v == 2 for row in tile for v in row)
                if count:
                    tiles.append((count, tile))

    if not tiles:
        return [[0 for _ in range(w)] for _ in range(h)]

    # The repeated tile is the motif.
    counts = {}
    for count, tile in tiles:
        counts[tile] = counts.get(tile, 0) + 1
    motif = max(counts, key=lambda t: (counts[t], sum(v == 2 for row in t for v in row)))

    masked_rows = []
    masked_cols = []
    for i in range(n):
        masked_rows.append(any(
            grid[i * pitch + a][j * pitch + b] == 3
            for j in range(n) for a in range(n) for b in range(n)
        ))
        masked_cols.append(any(
            grid[i * pitch + a][j * pitch + b] == 3
            for i0 in [] for a in [] for b in []
        ))
    # Check masked columns separately.
    for j in range(n):
        masked_cols[j] = any(
            grid[i * pitch + a][j * pitch + b] == 3
            for i in range(n) for a in range(n) for b in range(n)
        )

    out = [[0] * w for _ in range(h)]
    for i in range(n):
        for j in range(n):
            # A covered interior tile-row is reconstructed from the motif.
            # A covered tile-column is cleared.
            if masked_cols[j]:
                continue
            if masked_rows[i] and not (0 < i < n - 1):
                continue
            if motif[i][j] != 2:
                continue

            r, c = i * pitch, j * pitch
            for a in range(n):
                for b in range(n):
                    out[r + a][c + b] = motif[a][b]
            if motif[i][j] == 2:
                out[r + i][c + j] = 8

    return out
